This Python code is supposed to deduplicate a list while preserving order, but it is very slow on large inputs. Please refactor it and explain the complexity.

def dedup(items):
    result = []
    for x in items:
        found = False
        for y in result:
            if x == y:
                found = True
                break
        if not found:
            result.append(x)
    return result

def dedup_all(lists):
    out = []
    for l in lists:
        out.append(dedup(l))
    return out

